 * SPDX-License-Identifier: Apache-2.0
 *
 * 5x5 convolution, 1 input channel -> 64 output channels, hardwired weights.
 *
 * For every output pixel the chip computes 64 sums, one per filter f:
 *   y[f] = sum over ky,kx in 0..4 of w[f][ky][kx] * x[ky][kx]
 * (64 x 25 = 1600 multiply-accumulates). The weights live in a ROM built from
 * logic (src/weights_rom.v, generated by tools/gen_weights.py) that returns a
 * whole filter, 25 weights, per 6-bit address.
 *
 * The host streams the image one column of 5 pixels at a time (top to bottom).
 * Each column shifts into a 5x5 window from the right. Once 5 columns of a row
 * band are loaded, every further column produces one output pixel, so sliding
 * the window one pixel to the right costs only 5 input bytes. Results come out
 * as 64 exact signed 20-bit sums per pixel, in filter order, through a
 * read/ACK handshake.
 *
 * Datapath: nothing selects one of many values. The window is a ring of 25
 * byte registers in tap order (slot t = ky*5 + kx) and the current filter's
 * weights are a second ring beside it. Both rotate one slot every clock, so
 * the multiplier always reads slot 0 of each, and every register is fed only
 * from a nearby slot. This keeps the wiring local enough to route.
 *
 * Pins
 *   ui_in[7:0]   PIX       signed 8-bit pixel
 *   uio_in[0]    VALID     PIX is accepted on a rising clk edge while VALID=1
 *   uio_in[1]    START     with VALID: PIX is the top of the first column of a new row band
 *   uio_in[3:2]  BYTE_SEL  0..2: byte of the sign-extended 24-bit result (0 = LSB); 3: filter index
 *   uio_in[4]    ACK       high for one clock: the host has read the result
 *   uio_out[5]   IN_RDY    the column buffer has room for PIX
 *   uio_out[6]   ERR       sticky until reset: PIX sent while IN_RDY=0, or ACK with no result
 *   uio_out[7]   OUT_VALID the result register holds an unread result
 *   uo_out[7:0]  RESULT    byte BYTE_SEL of the result
 */

`default_nettype none

module tt_um_ejborcherding_conv7x7 (
    input  wire [7:0] ui_in,    // Dedicated inputs
    output wire [7:0] uo_out,   // Dedicated outputs
    input  wire [7:0] uio_in,   // IOs: Input path
    output wire [7:0] uio_out,  // IOs: Output path
    output wire [7:0] uio_oe,   // IOs: Enable path (active high: 0=input, 1=output)
    input  wire       ena,      // always 1 when the design is powered, so you can ignore it
    input  wire       clk,      // clock
    input  wire       rst_n     // reset_n - low to reset
);

  // 64 filters x 25 taps = 1600 weights
  localparam integer K     = 5;   // kernel is K x K
  localparam integer TAPS  = K * K;
  localparam integer FW    = 6;   // filter index bits = ROM address bits
  localparam integer ACC_W = 20;  // |sum| <= 25 * 16384 < 2^19

  // ---------------------------------------------------------------- inputs
  wire       in_valid = uio_in[0];
  wire       in_start = uio_in[1];
  wire [1:0] byte_sel = uio_in[3:2];
  wire       in_ack   = uio_in[4];

  // ----------------------------------------- column buffer and pixel ring
  reg  [8*K-1:0] col;        // pixel ky of the incoming column at col[8*ky +: 8]
  reg  [2:0]   col_cnt;      // pixels received; K = full
  reg          col_new_row;  // the column was begun with START
  reg  [8*TAPS-1:0] pring;   // pixel ring: slot t at pring[8*t +: 8]
  reg  [2:0]   win_cols;     // columns loaded since the row band began, saturates at K

  wire col_full = (col_cnt == K);

  // ----------------------------------------------- engine: stage 0 (issue)
  reg          running;
  reg [4:0]    tap;          // ring position: slot 0 holds tap ky*K + kx = tap
  reg [FW-1:0] filt;

  reg [ACC_W-1:0] out_data;
  reg [FW-1:0]    out_filt;
  reg             out_full;
  reg             err;

  wire ack       = in_ack & out_full;
  wire out_free  = ~out_full | ack;
  wire tap_last  = (tap == TAPS - 1);
  wire filt_last = (filt == {FW{1'b1}});

  // Both rings rotate on every clock, so the engine issues tap t when the
  // ring position is t. The last tap of a filter is held back until the
  // result register can take its sum. The filter's other taps are then simply
  // issued again on the next turn of the rings: tap 0 restarts the
  // accumulator, so the sum comes out the same. A slow host stalls the engine
  // instead of losing results.
  wire issue     = running & (~tap_last | out_free);

  // A full column enters the window while the engine is idle and the ring is
  // in tap order (position 0). The next pixel starts one clock after the
  // previous one ends.
  wire       shift     = col_full & ~running & (tap == 5'd0);
  wire [2:0] cols_next = col_new_row ? 3'd1 : (win_cols == K) ? win_cols : win_cols + 3'd1;
  wire       launch    = shift & (cols_next == K);

  // Pixel ring. At position 0 it is in tap order, so slot t holds pixel
  // (ky, kx) = (t / K, t % K). Every clock it rotates one slot toward slot 0
  // (slot t takes slot t+1, slot 0 wraps to slot TAPS-1) and the position
  // counts up, so slot 0 always holds the pixel for tap `tap`.
  //
  // A shift moves the window one column left and loads the new column into
  // the kx = K-1 slots. At position 0 that is the same move as a rotation,
  // except that those slots take the column instead of the wrapped value, and
  // the position stays at 0. So the inner slots never need a select at all.
  wire [8*TAPS-1:0] pring_next;
  genvar gt;
  generate
    for (gt = 0; gt < TAPS; gt = gt + 1) begin : g_slot
      wire [7:0] from_1 = pring[8*((gt + 1) % TAPS) +: 8];
      if (gt % K == K - 1) begin : g_edge
        assign pring_next[8*gt +: 8] = shift ? col[8*(gt / K) +: 8] : from_1;
      end else begin : g_inner
        assign pring_next[8*gt +: 8] = from_1;
      end
    end
  endgenerate

  // Weight ring: the current filter's 25 weights, rotating with the pixel
  // ring. The ROM is addressed by the filter loaded next: filter 0 while idle,
  // filt + 1 while running (wrapping to 0 for the next pixel). The address
  // changes once per filter, so the ROM output is stable long before it loads.
  reg  [8*TAPS-1:0] wring;   // slot t at wring[8*t +: 8]
  wire [8*TAPS-1:0] rom_word;
  wire [FW-1:0]     rom_filt = filt + {{(FW - 1){1'b0}}, running};

  conv_weights weights_rom (
      .filt(rom_filt),
      .w   (rom_word)
  );

  // ------------------------------------------ stage 1: registered operands
  reg              s1_valid, s1_first, s1_last;
  reg [FW-1:0]     s1_filt;
  reg signed [7:0] s1_w, s1_x;

  // ------------------------------------------------ stage 2: accumulate
  reg signed [ACC_W-1:0] acc;

  wire signed [15:0]      prod     = s1_w * s1_x;
  wire signed [ACC_W-1:0] acc_base = s1_first ? {ACC_W{1'b0}} : acc;
  wire signed [ACC_W-1:0] acc_next = acc_base + {{(ACC_W - 16){prod[15]}}, prod};

  always @(posedge clk) begin
    if (!rst_n) begin
      col_cnt     <= 3'd0;
      col_new_row <= 1'b0;
      win_cols    <= 3'd0;
      running     <= 1'b0;
      tap         <= 5'd0;
      filt        <= {FW{1'b0}};
      s1_valid    <= 1'b0;
      s1_first    <= 1'b0;
      s1_last     <= 1'b0;
      s1_filt     <= {FW{1'b0}};
      s1_w        <= 8'sd0;
      s1_x        <= 8'sd0;
      acc         <= {ACC_W{1'b0}};
      out_data    <= {ACC_W{1'b0}};
      out_filt    <= {FW{1'b0}};
      out_full    <= 1'b0;
      err         <= 1'b0;
    end else begin
      // rings rotate every clock; the position restarts at 0 after a shift
      pring <= pring_next;
      tap   <= (shift | tap_last) ? 5'd0 : tap + 5'd1;
      if (shift) begin
        win_cols    <= cols_next;
        col_cnt     <= 3'd0;
        col_new_row <= 1'b0;
      end

      // pixel input; START restarts the column even if it was partly filled
      if (in_valid & in_start) begin
        col[7:0]    <= ui_in;
        col_cnt     <= 3'd1;
        col_new_row <= 1'b1;
      end else if (in_valid & ~col_full) begin
        col[8*col_cnt +: 8] <= ui_in;
        col_cnt             <= col_cnt + 3'd1;
      end

      if ((in_valid & col_full) | (in_ack & ~out_full)) err <= 1'b1;

      // weight ring: load a filter while idle and at each filter boundary
      if (~running | (issue & tap_last)) wring <= rom_word;
      else wring <= {wring[7:0], wring[8*TAPS-1:8]};

      // stage 0: walk filt 0..63; the ring position walks the taps
      if (launch) begin
        running <= 1'b1;
        filt    <= {FW{1'b0}};
      end else if (issue & tap_last) begin
        filt <= filt + 1'b1;
        if (filt_last) running <= 1'b0;
      end

      // stage 0 -> stage 1
      s1_valid <= issue;
      if (issue) begin
        s1_w     <= wring[7:0];
        s1_x     <= pring[7:0];
        s1_first <= (tap == 5'd0);
        s1_last  <= tap_last;
        s1_filt  <= filt;
      end

      // stage 1 -> stage 2 (an ACK and a new result never land in the same cycle)
      if (ack) out_full <= 1'b0;
      if (s1_valid) begin
        acc <= acc_next;
        if (s1_last) begin
          out_data <= acc_next;
          out_filt <= s1_filt;
          out_full <= 1'b1;
        end
      end
    end
  end

  // ---------------------------------------------------------------- outputs
  wire [23:0] result24 = {{(24 - ACC_W){out_data[ACC_W-1]}}, out_data};

  reg [7:0] out_byte;
  always @(*) begin
    case (byte_sel)
      2'd0:    out_byte = result24[7:0];
      2'd1:    out_byte = result24[15:8];
      2'd2:    out_byte = result24[23:16];
      default: out_byte = {{(8 - FW){1'b0}}, out_filt};
    endcase
  end

  assign uo_out  = out_byte;
  assign uio_out = {out_full, err, ~col_full, 5'b0};
  assign uio_oe  = 8'b1110_0000;

  // List all unused inputs to prevent warnings
  wire _unused = &{ena, uio_in[7:5], 1'b0};

endmodule
